$("form[data-ajax]").submit(function (e) {
  e.preventDefault();

  // Tạo FormData từ form
  let formData = new FormData(this);

  $.ajax({
    url: $(this).attr("action"),
    data: formData,
    type: $(this).attr("method"),
    dataType: "json",
    contentType: false, // Để gửi đúng định dạng multipart/form-data
    processData: false, // Không xử lý dữ liệu theo cách mặc định
    statusCode: {
      400: function () {
        noti("error", "400 status code! user error");
      },
      500: function () {
        noti("error", "500 status code! server error");
      },
    },
    success: (data) => {
      if (!data) {
        noti("error", "400 status code! user error");
      } else {
        if (!data.redirect || typeof data.redirect === "undefined") {
          noti(data.status, data.message);
        } else {
          if (data.status === "success") {
            setTimeout(() => {
              window.location.href = data.redirect;
            }, 700);
          }
          noti(data.status, data.message);
        }
      }
    },
    error: function (request) {
      noti("error", "server error");
    },
  });
});

function noti(status, message) {
  Swal.fire({
    text: message,
    icon: status,
  });
}
